    public static floatQuat Slerp(floatQuat a, floatQuat b, float amount)
    {
        var t = amount;

        var cosOmega = Dot(a, b);

        var flip = false;

        if (cosOmega < 0)
        {
            flip = true;
            cosOmega = -cosOmega;
        }

        float s1,
            s2;

        if (cosOmega > 1 - SlerpEpsilon)
        {
            // Too close, do straight linear interpolation.
            s1 = 1 - t;
            s2 = flip ? -t : t;
        }
        else
        {
            var omega = float.Acos(cosOmega);
            var invSinOmega = 1 / float.Sin(omega);

            s1 = float.Sin((1 - t) * omega) * invSinOmega;
            s2 = flip ? -float.Sin(t * omega) * invSinOmega : float.Sin(t * omega) * invSinOmega;
        }

        return a * s1 + b * s2;
    }

